/** Public manual illustrations use staged, non-personal application data. */
export interface ManualGuideStep {
  title: string;
  instruction: string;
  image: string;
  alt: string;
  width: number;
  height: number;
}

export interface ManualGuide {
  title: string;
  summary: string;
  /** A short, reader-facing boundary, e.g. a staged editorial reading. */
  note?: string;
  steps: ManualGuideStep[];
}

export type ManualGuides = Record<string, ManualGuide>;
// @ts-expect-error — jsdom ships JS only; no @types/jsdom is installed.
import { JSDOM } from "jsdom";
import { Editor, type EditorOptions } from "@tiptap/core";
import { StarterKit } from "@tiptap/starter-kit";
import { CommentMark } from "./extensions/comment-mark";
import { PersonaNoteMark } from "./extensions/persona-note-mark";
import { SuggestionMark } from "./extensions/suggestion-mark";
import { PageBreakNode } from "./extensions/page-break-node";

/**
 * Tiptap + JSDOM test harness. The project's editor mounts inside a
 * Qwik component, which is too much ceremony to drive under test; the
 * extensions and the documents they operate on, however, are pure and
 * cover the lion's share of the bug surface (mark shape, anchor
 * preservation, setComment command, etc.). This file stands up a
 * minimal JSDOM, installs the project extensions on a fresh editor,
 * and yields the editor for the test to drive.
 *
 * Tests should not import this file directly. They use the `withEditor`
 * helper, which handles setup, teardown, and DOM global management in
 * one call.
 */

export interface EditorHarness {
  dom: JSDOM;
  editor: Editor;
  host: HTMLElement;
  /** Convenience for tests that need to read the rendered HTML. */
  html: () => string;
}

export interface WithEditorOptions {
  content?: string;
  /** Extra extensions on top of the project's standard set. */
  extensions?: EditorOptions["extensions"];
}

/**
 * Standard Tiptap extensions used by the project's editor.
 *
 * The pagination extension is deliberately absent: JSDOM has no layout
 * engine, so every `offsetHeight` it reports is zero and the measurements
 * would be meaningless. Pagination's arithmetic is tested directly against
 * `pagination-geometry.ts`, and its DOM behaviour in the Playwright suite.
 */
export const projectExtensions = [
  StarterKit,
  CommentMark,
  PersonaNoteMark,
  SuggestionMark,
  PageBreakNode,
];

/**
 * Mount a Tiptap editor in a fresh JSDOM and yield it to the test.
 * Installs DOM globals for the lifetime of the callback, then tears
 * them down so a follow-up test gets a clean slate.
 */
export async function withEditor(
  opts: WithEditorOptions | ((harness: EditorHarness) => Promise<void> | void),
  run?: (harness: EditorHarness) => Promise<void> | void,
): Promise<void> {
  // Backwards-compatible: `withEditor(cb)` still works.
  if (typeof opts === "function") {
    run = opts as (h: EditorHarness) => Promise<void> | void;
    opts = {};
  }
  const options = (opts ?? {}) as WithEditorOptions;

  const dom = new JSDOM(
    `<!DOCTYPE html><html><body><div id="editor-mount"></div></body></html>`,
  );

  const previousGlobals: Record<string, PropertyDescriptor | undefined> = {};
  const install = (key: string, value: unknown) => {
    previousGlobals[key] = Object.getOwnPropertyDescriptor(globalThis, key);
    Object.defineProperty(globalThis, key, {
      configurable: true,
      writable: true,
      value,
    });
  };

  install("document", dom.window.document);
  install("window", dom.window);
  install("HTMLElement", dom.window.HTMLElement);
  install("Node", dom.window.Node);
  install("Element", dom.window.Element);
  install("navigator", dom.window.navigator);
  install("getComputedStyle", dom.window.getComputedStyle);
  // Tiptap's `keyboardShortcut` command synthesises a real KeyboardEvent to
  // run it through the keymap, so a test that exercises a binding needs the
  // constructor on the global rather than only on the JSDOM window.
  install("Event", dom.window.Event);
  install("KeyboardEvent", dom.window.KeyboardEvent);
  install("MouseEvent", dom.window.MouseEvent);
  install(
    "requestAnimationFrame",
    (cb: FrameRequestCallback) =>
      setTimeout(() => cb(0), 0) as unknown as number,
  );
  install("cancelAnimationFrame", (id: number) => clearTimeout(id));

  const host = document.getElementById("editor-mount")!;
  const editor = new Editor({
    element: host,
    extensions: [...projectExtensions, ...(options.extensions ?? [])],
    content: options.content ?? "",
  });

  const harness: EditorHarness = {
    dom,
    editor,
    host,
    html: () => editor.getHTML(),
  };

  try {
    await run?.(harness);
  } finally {
    editor.destroy();
    dom.window.close();
    for (const key of Object.keys(previousGlobals)) {
      const descriptor = previousGlobals[key];
      if (descriptor) Object.defineProperty(globalThis, key, descriptor);
      else Reflect.deleteProperty(globalThis, key);
    }
  }
}
import { expect, test, type Page } from "@playwright/test";

async function seedFolio(page: Page, html: string) {
  await page.goto("/");
  await page.evaluate(
    async ({ html }) => {
      const db: IDBDatabase = await new Promise((resolve, reject) => {
        const req = indexedDB.open("twyne", 2);
        req.onupgradeneeded = () => {
          const d = req.result;
          for (const [name, keyPath] of [
            ["folios", "id"],
            ["folio-content", "folioId"],
            ["brief", "folioId"],
            ["comments", "id"],
            ["personas", "id"],
            ["meta", "key"],
            ["ai-settings", "key"],
            ["lix-blob", "key"],
            ["voice-notes", "id"],
          ] as const) {
            if (!d.objectStoreNames.contains(name)) {
              d.createObjectStore(name, { keyPath });
            }
          }
        };
        req.onsuccess = () => resolve(req.result);
        req.onerror = () => reject(req.error);
      });

      const now = Date.now();
      const id = "e2e-formatting";
      await new Promise<void>((resolve, reject) => {
        const t = db.transaction(
          ["folios", "folio-content", "meta"],
          "readwrite",
        );
        t.objectStore("folios").put({
          id,
          name: "Formatting fixture",
          type: "draft",
          createdAt: now,
          updatedAt: now,
          // Explicit: an unset mode resolves to continuous now that the editor
          // defaults to scrolling, and `openEditor` waits on a pagination
          // measurement that continuous mode never performs.
          layout: { pagination: "paginated" },
        });
        t.objectStore("folio-content").put({
          folioId: id,
          html,
          updatedAt: now,
        });
        t.objectStore("meta").put({
          key: "active-folio-id",
          value: id,
          updatedAt: now,
        });
        t.oncomplete = () => resolve();
        t.onerror = () => reject(t.error);
      });
    },
    { html },
  );
}

async function openEditor(page: Page, html: string) {
  await seedFolio(page, html);
  await page.goto("/editor/");
  await expect(page.locator(".ProseMirror")).toBeVisible({ timeout: 20_000 });
  await page.waitForFunction(
    () => (window as any).__twynePagination?.measureCount > 0,
    undefined,
    { timeout: 20_000 },
  );
}

async function selectAllText(page: Page) {
  const pm = page.locator(".ProseMirror");
  await pm.click();
  await page.keyboard.press("ControlOrMeta+A");
}

test.describe("word-style formatting toolbar", () => {
  test("applies literal text and highlight colours through the pickers", async ({
    page,
  }) => {
    await openEditor(page, "<p>Colour this sentence.</p>");
    await selectAllText(page);

    await page
      .getByRole("button", { name: "Text colour", exact: true })
      .click();
    await page.getByRole("button", { name: "Sienna", exact: true }).click();
    await expect(
      page.locator('.ProseMirror span[style*="color"]'),
    ).toContainText("Colour this sentence.");

    await selectAllText(page);
    await page
      .getByRole("button", { name: "Choose highlight colour", exact: true })
      .click();
    await page.getByRole("button", { name: "Sky", exact: true }).click();
    const mark = page.locator('.ProseMirror mark[data-color="#cfe0f2"]');
    await expect(mark).toContainText("Colour this sentence.");
  });

  test("applies font, point size, line spacing, paragraph spacing and keep-with-next", async ({
    page,
  }) => {
    await openEditor(page, "<p>First paragraph.</p><p>Second paragraph.</p>");
    const first = page.locator(".ProseMirror > p").first();
    await first.click();
    await page.keyboard.press("Home");
    await page.keyboard.press("Shift+End");

    await page
      .getByRole("button", { name: "Type options", exact: true })
      .click();
    await page.getByRole("combobox", { name: "Font family" }).selectOption({
      label: "Special Elite",
    });
    await page
      .getByRole("combobox", { name: "Font size" })
      .selectOption("14pt");
    await page.getByRole("button", { name: "1.5", exact: true }).click();
    await page
      .getByRole("combobox", { name: "Space before paragraph" })
      .selectOption("12");
    await page
      .getByRole("combobox", { name: "Space after paragraph" })
      .selectOption("18");
    await page
      .getByRole("checkbox", { name: "Keep paragraph with next" })
      .check();

    await expect(first).toHaveAttribute("data-space-before", "12");
    await expect(first).toHaveAttribute("data-space-after", "18");
    await expect(first).toHaveAttribute("data-keep-with-next", "true");
    await expect(first).toHaveAttribute("style", /line-height:\s*1\.5/);
    await expect(first.locator("span")).toHaveCSS("font-size", "18.6667px");
    await expect(first.locator("span")).toHaveCSS(
      "font-family",
      '"Special Elite", Courier, monospace',
    );
  });

  test("case changes preserve inline marks", async ({ page }) => {
    await openEditor(
      page,
      "<p><strong>the fall</strong> of <em>the house</em></p>",
    );
    await selectAllText(page);
    await page
      .getByRole("button", { name: "Type options", exact: true })
      .click();
    await page.getByRole("button", { name: "title case" }).click();

    await expect(page.locator(".ProseMirror strong")).toHaveText("The Fall");
    await expect(page.locator(".ProseMirror em")).toHaveText("the House");
    await expect(page.locator(".ProseMirror p")).toHaveText(
      "The Fall of the House",
    );
  });

  test("clear formatting removes marks and paragraph geometry", async ({
    page,
  }) => {
    await openEditor(
      page,
      '<p data-space-before="12" data-space-after="18" data-keep-with-next="true" style="line-height: 1.5"><strong>Marked</strong></p>',
    );
    await selectAllText(page);
    await page
      .getByRole("button", { name: "Clear formatting", exact: true })
      .click();

    const paragraph = page.locator(".ProseMirror > p");
    await expect(paragraph.locator("strong")).toHaveCount(0);
    await expect(paragraph).not.toHaveAttribute("data-space-before", /.+/);
    await expect(paragraph).not.toHaveAttribute("data-space-after", /.+/);
    await expect(paragraph).not.toHaveAttribute("data-keep-with-next", /.+/);
  });

  test("paragraph spacing invalidates pagination measurements", async ({
    page,
  }) => {
    const body = Array.from(
      { length: 18 },
      (_, i) => `<p>Paragraph ${i}. ${"Measured prose. ".repeat(12)}</p>`,
    ).join("");
    await openEditor(page, body);
    const before = await page.evaluate(
      () => (window as any).__twynePagination.measureCount,
    );

    await page.locator(".ProseMirror > p").first().click();
    await page
      .getByRole("button", { name: "Type options", exact: true })
      .click();
    await page
      .getByRole("combobox", { name: "Space after paragraph" })
      .selectOption("24");

    await page.waitForFunction(
      (count) => (window as any).__twynePagination.measureCount > count,
      before,
      { timeout: 10_000 },
    );
    await expect(page.locator(".ProseMirror > p").first()).toHaveAttribute(
      "data-space-after",
      "24",
    );
  });
});

/**
 * The drop cap is a `::first-letter` rule, which outranks the inline
 * font-family and font-size the type controls write onto the surrounding
 * span. Hard-coding the display face there meant a manuscript set in
 * Special Elite kept a Fraunces drop cap — the most prominent glyph on
 * page one, visibly ignoring the writer — and 4.2em of a large size blew
 * the letter up past the height of the sheet.
 */
test.describe("drop cap follows the writer's type", () => {
  test("takes the chosen family and stays within the page", async ({
    page,
  }) => {
    await openEditor(page, "<p>First paragraph here, with a drop cap.</p>");
    const first = page.locator(".ProseMirror > p").first();

    const dropCap = () =>
      first.evaluate((el) => {
        const fl = getComputedStyle(el, "::first-letter");
        return {
          family: fl.fontFamily,
          size: Number.parseFloat(fl.fontSize),
        };
      });

    // The house look at the default body size is unchanged.
    expect((await dropCap()).size).toBeCloseTo(75.6, 0);

    await selectAllText(page);
    await page
      .getByRole("button", { name: "Type options", exact: true })
      .click();
    await page.getByRole("combobox", { name: "Font family" }).selectOption({
      label: "Special Elite",
    });
    await page
      .getByRole("combobox", { name: "Font size" })
      .selectOption("36pt");

    await expect
      .poll(async () => (await dropCap()).family)
      .toContain("Special Elite");
    // 4.2em of 48px would be 201.6px — taller than the text block it opens.
    expect((await dropCap()).size).toBeLessThanOrEqual(80);
  });
});

