import {
  $,
  component$,
  type JSXOutput,
  type NoSerialize,
  type PropFunction,
  type QRL,
} from "@qwik.dev/core";
import {
  focusOutlineHeading,
  type DocumentOutlineHeading,
  type DocumentOutlineModel,
  type OutlineFocusableEditor,
} from "../../utils/document-outline";

export interface DocumentOutlineProps {
  outline: DocumentOutlineModel | readonly DocumentOutlineHeading[];
  activeId?: string | null;
  editor?: NoSerialize<OutlineFocusableEditor>;
  onNavigate$?: PropFunction<(heading: DocumentOutlineHeading) => void>;
  label?: string;
  emptyLabel?: string;
}

function outlineItems(
  outline: DocumentOutlineProps["outline"],
): readonly DocumentOutlineHeading[] {
  return Array.isArray(outline)
    ? outline
    : (outline as DocumentOutlineModel).items;
}

/**
 * DOM fallback for consumers that render generated ids directly onto their
 * headings. The editor integration normally supplies the live Tiptap editor,
 * but this keeps the navigation component useful in published/static readers.
 */
export function focusOutlineHeadingElement(
  id: string,
  root: ParentNode = document,
): boolean {
  const escaped =
    typeof CSS !== "undefined" && typeof CSS.escape === "function"
      ? CSS.escape(id)
      : id.replace(/["\\]/g, "\\$&");
  const element = root.querySelector<HTMLElement>(
    `[data-outline-id="${escaped}"], #${escaped}`,
  );
  if (!element) return false;
  if (!element.hasAttribute("tabindex")) element.setAttribute("tabindex", "-1");
  element.focus({ preventScroll: true });
  element.scrollIntoView({ block: "center", behavior: "auto" });
  return true;
}

function renderBranch(
  headings: readonly DocumentOutlineHeading[],
  props: DocumentOutlineProps,
  navigate$: QRL<(heading: DocumentOutlineHeading) => void>,
): JSXOutput {
  return (
    <ol class="m-0 list-none p-0" role="list">
      {headings.map((heading) => {
        const active = props.activeId === heading.id;
        return (
          <li key={heading.id} class="m-0 p-0">
            <button
              type="button"
              class={[
                "group flex w-full items-start gap-2 rounded-md px-2 py-1.5 text-left",
                "text-sm leading-5 transition-colors duration-150",
                "focus-visible:outline-2 focus-visible:outline-offset-1",
                active
                  ? "bg-[var(--color-paper-2)] font-semibold text-[var(--color-ink)]"
                  : "text-[var(--color-ink-muted)] hover:bg-[var(--color-paper-2)] hover:text-[var(--color-ink)]",
              ]}
              aria-current={active ? "location" : undefined}
              title={`Go to ${heading.label}`}
              onClick$={() => navigate$(heading)}
            >
              <span
                aria-hidden="true"
                class="mt-[0.15rem] w-4 shrink-0 text-right font-mono text-[0.65rem] text-[var(--color-ink-muted)] opacity-70"
              >
                {heading.level}
              </span>
              <span class="min-w-0 flex-1 break-words">{heading.label}</span>
            </button>
            {heading.children.length > 0 && (
              <div class="ml-3 border-l border-[var(--color-paper-3)] pl-1">
                {renderBranch(heading.children, props, navigate$)}
              </div>
            )}
          </li>
        );
      })}
    </ol>
  );
}

/**
 * Compact outline navigation for the editor sidebar.
 *
 * The component owns no editor state and can therefore be integrated without
 * racing the central editor. A consumer may pass the live editor, provide an
 * explicit navigation callback, or rely on generated ids in static HTML.
 */
export const DocumentOutline = component$<DocumentOutlineProps>((props) => {
  const items = outlineItems(props.outline);
  const navigate$ = $((heading: DocumentOutlineHeading) => {
    if (props.onNavigate$) {
      void props.onNavigate$(heading);
      return;
    }
    if (props.editor && focusOutlineHeading(props.editor, heading)) return;
    if (typeof document !== "undefined") {
      focusOutlineHeadingElement(heading.id);
    }
  });

  return (
    <nav
      aria-label={props.label || "Document outline"}
      class="min-h-0 overflow-y-auto"
    >
      {items.length > 0 ? (
        renderBranch(items, props, navigate$)
      ) : (
        <p
          class="m-0 px-2 py-3 text-sm leading-5 text-[var(--color-ink-muted)]"
          role="status"
        >
          {props.emptyLabel || "Add a heading to build the outline."}
        </p>
      )}
    </nav>
  );
});
import {
  $,
  component$,
  sync$,
  useSignal,
  useVisibleTask$,
  type NoSerialize,
  type PropFunction,
} from "@qwik.dev/core";
import type { Editor } from "@tiptap/core";
import { getFindReplaceState } from "./extensions/find-replace";

export interface FindReplacePanelProps {
  /** Live Tiptap editor. The coordinator wires this during central integration. */
  editor?: NoSerialize<Editor> | null;
  onClose$?: PropFunction<() => void>;
  initialQuery?: string;
}

function findSnapshot(editor: Editor) {
  const state = getFindReplaceState(editor.state);
  const count = state?.matches.length ?? 0;
  return {
    count,
    current: count > 0 && state ? state.activeIndex + 1 : 0,
    error: state?.error ?? null,
  };
}

/**
 * Compact, keyboard-friendly Find/Replace surface. Search changes update only
 * plugin metadata and decorations; replacement commands are the sole document
 * mutations, so opening, navigating, or closing the panel cannot dirty HTML or
 * create undo entries.
 */
export const FindReplacePanel = component$<FindReplacePanelProps>((props) => {
  const search = useSignal(props.initialQuery ?? "");
  const replacement = useSignal("");
  const caseSensitive = useSignal(false);
  const wholeWord = useSignal(false);
  const regex = useSignal(false);
  const matchCount = useSignal(0);
  const activeMatch = useSignal(0);
  const searchError = useSignal<string | null>(null);

  // Subscribe to Tiptap transactions so the counter follows navigation and
  // document edits without asking the parent editor to mirror plugin state.
  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(({ cleanup, track }) => {
    track(() => props.editor);
    const editor = props.editor;
    if (!editor || editor.isDestroyed) return;
    const refresh = () => {
      const state = findSnapshot(editor);
      matchCount.value = state.count;
      activeMatch.value = state.current;
      searchError.value = state.error;
    };
    editor.on("transaction", refresh);
    if (search.value) {
      editor.commands.setFindQuery(search.value, {
        caseSensitive: caseSensitive.value,
        wholeWord: wholeWord.value,
        regex: regex.value,
      });
    }
    refresh();
    cleanup(() => {
      editor.off("transaction", refresh);
    });
  });

  const updateQuery = $(() => {
    const editor = props.editor;
    if (!editor || editor.isDestroyed) return;
    editor.commands.setFindQuery(search.value, {
      caseSensitive: caseSensitive.value,
      wholeWord: wholeWord.value,
      regex: regex.value,
    });
    const state = findSnapshot(editor);
    matchCount.value = state.count;
    activeMatch.value = state.current;
    searchError.value = state.error;
  });

  const close = $(() => {
    const editor = props.editor;
    if (editor && !editor.isDestroyed) editor.commands.clearFindQuery();
    void props.onClose$?.();
  });

  const onSearchKey = $((event: KeyboardEvent) => {
    if (event.key === "Enter") {
      if (event.shiftKey) props.editor?.commands.findPrevious();
      else props.editor?.commands.findNext();
      const editor = props.editor;
      if (editor) {
        const state = findSnapshot(editor);
        matchCount.value = state.count;
        activeMatch.value = state.current;
        searchError.value = state.error;
      }
    } else if (event.key === "Escape") {
      void close();
    }
  });
  const preventSearchNavigation = sync$((event: KeyboardEvent) => {
    if (event.key === "Enter" || event.key === "Escape") {
      event.preventDefault();
    }
  });
  const preventEscape = sync$((event: KeyboardEvent) => {
    if (event.key === "Escape") event.preventDefault();
  });

  const count = matchCount.value;
  const current = activeMatch.value;
  const hasActive = current > 0;

  return (
    <section
      class="twyne-find-replace-panel"
      role="search"
      aria-label="Find and replace"
      style={{
        display: "grid",
        gap: "0.55rem",
        padding: "0.75rem",
        border: "1px solid color-mix(in srgb, currentColor 18%, transparent)",
        borderRadius: "0.65rem",
        background: "var(--color-paper, #fffdf8)",
        boxShadow: "0 12px 32px rgba(27, 22, 15, 0.14)",
        minWidth: "min(34rem, calc(100vw - 2rem))",
      }}
    >
      <div style={{ display: "flex", gap: "0.4rem", alignItems: "center" }}>
        <label style={{ flex: "1" }}>
          <span class="sr-only">Find</span>
          <input
            type="search"
            value={search.value}
            placeholder="Find"
            autofocus
            aria-invalid={searchError.value ? "true" : undefined}
            aria-describedby={
              searchError.value ? "find-replace-error" : undefined
            }
            onInput$={(event) => {
              search.value = (event.target as HTMLInputElement).value;
              void updateQuery();
            }}
            onKeyDown$={[preventSearchNavigation, onSearchKey]}
            style={{ width: "100%" }}
          />
        </label>
        <output
          aria-live="polite"
          aria-label={`${current} of ${count} matches`}
          style={{
            minWidth: "4.5rem",
            textAlign: "center",
            fontVariantNumeric: "tabular-nums",
          }}
        >
          {current} / {count}
        </output>
        <button
          type="button"
          aria-label="Previous match"
          title="Previous match (Shift+Enter)"
          disabled={count === 0}
          onClick$={() => {
            props.editor?.commands.findPrevious();
            const editor = props.editor;
            if (!editor) return;
            const state = findSnapshot(editor);
            matchCount.value = state.count;
            activeMatch.value = state.current;
          }}
        >
          ↑
        </button>
        <button
          type="button"
          aria-label="Next match"
          title="Next match (Enter)"
          disabled={count === 0}
          onClick$={() => {
            props.editor?.commands.findNext();
            const editor = props.editor;
            if (!editor) return;
            const state = findSnapshot(editor);
            matchCount.value = state.count;
            activeMatch.value = state.current;
          }}
        >
          ↓
        </button>
        <button
          type="button"
          aria-label="Close find and replace"
          onClick$={close}
        >
          ×
        </button>
      </div>

      <div style={{ display: "flex", gap: "0.4rem", alignItems: "center" }}>
        <label style={{ flex: "1" }}>
          <span class="sr-only">Replace with</span>
          <input
            type="text"
            value={replacement.value}
            placeholder="Replace with"
            onInput$={(event) => {
              replacement.value = (event.target as HTMLInputElement).value;
            }}
            onKeyDown$={[
              preventEscape,
              $((event: KeyboardEvent) => {
                if (event.key === "Escape") void close();
              }),
            ]}
            style={{ width: "100%" }}
          />
        </label>
        <button
          type="button"
          disabled={!hasActive}
          onClick$={() => {
            props.editor?.commands.replaceCurrent(replacement.value);
            const editor = props.editor;
            if (!editor) return;
            const state = findSnapshot(editor);
            matchCount.value = state.count;
            activeMatch.value = state.current;
          }}
        >
          Replace
        </button>
        <button
          type="button"
          disabled={count === 0}
          onClick$={() => {
            props.editor?.commands.replaceAll(replacement.value);
            const editor = props.editor;
            if (!editor) return;
            const state = findSnapshot(editor);
            matchCount.value = state.count;
            activeMatch.value = state.current;
          }}
        >
          Replace all
        </button>
      </div>

      <div style={{ display: "flex", gap: "0.85rem", flexWrap: "wrap" }}>
        <label>
          <input
            type="checkbox"
            checked={caseSensitive.value}
            onChange$={(event) => {
              caseSensitive.value = (event.target as HTMLInputElement).checked;
              void updateQuery();
            }}
          />{" "}
          Match case
        </label>
        <label>
          <input
            type="checkbox"
            checked={wholeWord.value}
            onChange$={(event) => {
              wholeWord.value = (event.target as HTMLInputElement).checked;
              void updateQuery();
            }}
          />{" "}
          Whole word
        </label>
        <label>
          <input
            type="checkbox"
            checked={regex.value}
            onChange$={(event) => {
              regex.value = (event.target as HTMLInputElement).checked;
              void updateQuery();
            }}
          />{" "}
          Regular expression
        </label>
      </div>

      {searchError.value && (
        <p
          id="find-replace-error"
          role="alert"
          style={{ margin: 0, color: "var(--color-accent-red)" }}
        >
          {searchError.value}
        </p>
      )}
    </section>
  );
});
import {
  component$,
  useSignal,
  useVisibleTask$,
  type PropFunction,
} from "@qwik.dev/core";
import type {
  EditorCommandContext,
  EditorCommandId,
} from "../../utils/editor-commands";
import {
  fuzzySlashCommands,
  type SlashCommandCandidate,
} from "../../utils/slash-command-filter";
import type { ShortcutPlatform } from "../../utils/keybindings";

interface SlashCommandMenuProps {
  open: boolean;
  query: string;
  context?: EditorCommandContext;
  platform?: ShortcutPlatform;
  /** Fixed viewport coordinates supplied by the TipTap integration. */
  left: number;
  top: number;
  onSelect$: PropFunction<(commandId: EditorCommandId) => void>;
  onClose$: PropFunction<() => void>;
}

function slashGroup(candidate: SlashCommandCandidate): string {
  return candidate.command.slash?.group ?? "Commands";
}

type SlashSelectionId = EditorCommandId | null;

/** Keep selection attached to a command, even when filtering reorders rows. */
export function reconcileSlashSelection(
  candidates: SlashCommandCandidate[],
  selectedCommandId: SlashSelectionId,
): SlashSelectionId {
  if (
    selectedCommandId &&
    candidates.some((candidate) => candidate.command.id === selectedCommandId)
  ) {
    return selectedCommandId;
  }
  return (candidates[0]?.command.id as EditorCommandId | undefined) ?? null;
}

/** Move through the visible result set rather than the unfiltered registry. */
export function moveSlashSelection(
  candidates: SlashCommandCandidate[],
  selectedCommandId: SlashSelectionId,
  direction: 1 | -1,
): SlashSelectionId {
  if (candidates.length === 0) return null;
  const currentId = reconcileSlashSelection(candidates, selectedCommandId);
  const currentIndex = candidates.findIndex(
    (candidate) => candidate.command.id === currentId,
  );
  const nextIndex =
    (currentIndex + direction + candidates.length) % candidates.length;
  return candidates[nextIndex].command.id as EditorCommandId;
}

function optionId(commandId: string): string {
  return `slash-command-${commandId.replace(/[^a-zA-Z0-9_-]/g, "-")}`;
}

/** Keyboard-navigable slash menu, driven entirely by the command registry. */
export const SlashCommandMenu = component$<SlashCommandMenuProps>((props) => {
  const selectedCommandId = useSignal<SlashSelectionId>(null);
  const candidates: SlashCommandCandidate[] = fuzzySlashCommands(
    props.query,
    props.context,
    props.platform ?? "mac",
  );
  const visibleSelection = reconcileSlashSelection(
    candidates,
    selectedCommandId.value,
  );

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(({ cleanup, track }) => {
    const open = track(() => props.open);
    const query = track(() => props.query);
    const currentCandidates = fuzzySlashCommands(
      query,
      props.context,
      props.platform ?? "mac",
    );
    selectedCommandId.value = reconcileSlashSelection(
      currentCandidates,
      selectedCommandId.value,
    );
    if (!open) return;

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        event.preventDefault();
        void props.onClose$();
        return;
      }
      // Resolve results at keypress time. A rapid query change must never leave
      // Enter acting on the candidate array from the prior render.
      const visibleCandidates = fuzzySlashCommands(
        props.query,
        props.context,
        props.platform ?? "mac",
      );
      if (visibleCandidates.length === 0) return;
      if (event.key === "ArrowDown") {
        event.preventDefault();
        selectedCommandId.value = moveSlashSelection(
          visibleCandidates,
          selectedCommandId.value,
          1,
        );
      } else if (event.key === "ArrowUp") {
        event.preventDefault();
        selectedCommandId.value = moveSlashSelection(
          visibleCandidates,
          selectedCommandId.value,
          -1,
        );
      } else if (event.key === "Enter") {
        if (event.isComposing) return;
        event.preventDefault();
        const currentSelection = reconcileSlashSelection(
          visibleCandidates,
          selectedCommandId.value,
        );
        const selected = visibleCandidates.find(
          (candidate) => candidate.command.id === currentSelection,
        );
        if (selected)
          void props.onSelect$(selected.command.id as EditorCommandId);
      }
    };
    window.addEventListener("keydown", onKeyDown, true);
    cleanup(() => window.removeEventListener("keydown", onKeyDown, true));
  });

  if (!props.open) return null;

  return (
    <div
      class="fixed w-72 overflow-hidden border border-[var(--color-paper-3)] bg-[var(--color-paper)] shadow-lg"
      style={{
        left: `${props.left}px`,
        top: `${props.top}px`,
        zIndex: "var(--z-dropdown)",
        borderRadius: "2px",
      }}
      role="listbox"
      aria-label="Insert command"
      aria-activedescendant={
        visibleSelection ? optionId(visibleSelection) : undefined
      }
    >
      <p
        class="border-b border-[var(--color-paper-3)] px-3 py-2 text-[0.62rem] uppercase tracking-[0.16em] text-[var(--color-ink-muted)]"
        style={{ fontFamily: "var(--font-typewriter)" }}
      >
        Insert {props.query ? `“${props.query}”` : "a block"}
      </p>

      {candidates.length === 0 ? (
        <p
          class="px-3 py-5 text-center text-sm text-[var(--color-ink-muted)]"
          style={{ fontFamily: "var(--font-serif)" }}
        >
          No commands match.
        </p>
      ) : (
        <div class="max-h-80 overflow-y-auto py-1">
          {candidates.map((candidate, index) => {
            const group = slashGroup(candidate);
            const showGroup =
              index === 0 || slashGroup(candidates[index - 1]) !== group;
            const isSelected = candidate.command.id === visibleSelection;
            return (
              <div key={candidate.command.id}>
                {showGroup && (
                  <p
                    class="border-y border-[var(--color-paper-3)] bg-[var(--color-paper-soft)] px-3 py-1 text-[0.58rem] uppercase tracking-[0.16em] text-[var(--color-ink-muted)] first:border-t-0"
                    style={{ fontFamily: "var(--font-typewriter)" }}
                  >
                    {group}
                  </p>
                )}
                <button
                  id={optionId(candidate.command.id)}
                  type="button"
                  role="option"
                  aria-selected={isSelected}
                  class={`flex w-full items-center gap-3 px-3 py-2 text-left ${
                    isSelected
                      ? "bg-[var(--color-paper-2)] text-[var(--color-vermilion)]"
                      : "text-[var(--color-ink)] hover:bg-[var(--color-paper-soft)]"
                  }`}
                  onMouseEnter$={() => {
                    selectedCommandId.value = candidate.command
                      .id as EditorCommandId;
                  }}
                  onMouseDown$={(event) => event.preventDefault()}
                  onClick$={() =>
                    props.onSelect$(candidate.command.id as EditorCommandId)
                  }
                >
                  <span class="min-w-0 flex-1">
                    <span
                      class="block truncate text-sm font-medium"
                      style={{ fontFamily: "var(--font-sans)" }}
                    >
                      {candidate.command.label}
                    </span>
                    <span
                      class="mt-0.5 block truncate text-xs text-[var(--color-ink-muted)]"
                      style={{ fontFamily: "var(--font-serif)" }}
                    >
                      {candidate.command.description}
                    </span>
                  </span>
                  {candidate.shortcut && (
                    <kbd
                      class="text-[0.62rem] text-[var(--color-ink-muted)]"
                      style={{ fontFamily: "var(--font-typewriter)" }}
                    >
                      {candidate.shortcut}
                    </kbd>
                  )}
                </button>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
});

