import { chromium, expect } from '@playwright/test';
import { mkdir, writeFile } from 'node:fs/promises';
import sharp from 'sharp';

export const root = new URL('../../../../../', import.meta.url).pathname;
export const recording = new URL('./', import.meta.url).pathname;
export const assets = `${root}public/assets/manual/editorial/`;
export const captures = [];

export async function boot() {
  await mkdir(assets, { recursive: true });
  const browser = await chromium.launch({ headless: true, executablePath: '/home/diogenes/.cache/ms-playwright/chromium_headless_shell-1228/chrome-headless-shell-linux64/chrome-headless-shell' });
  const context = await browser.newContext({ viewport: { width: 1280, height: 950 }, reducedMotion: 'reduce', recordVideo: { dir: recording, size: { width: 1280, height: 950 } } });
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.addInitScript(() => {
    const hideDiagnostics = () => {
      for (const element of document.querySelectorAll('body *')) {
        if (element.textContent === 'Click-to-Source: Alt') element.style.display = 'none';
      }
    };
    document.addEventListener('DOMContentLoaded', () => { hideDiagnostics(); new MutationObserver(hideDiagnostics).observe(document.body, { childList: true, subtree: true }); });
  });
  await page.route('**/__manual-editorial-seed', route => route.fulfill({ contentType: 'text/html', body: '<!doctype html><title>Sample manuscript</title>' }));
  await page.goto('http://127.0.0.1:5180/__manual-editorial-seed');
  await page.evaluate(async () => {
    const idb = await import('/src/utils/idb.ts');
    const uc = await import('/src/utils/user-comments.ts');
    const bib = await import('/src/utils/bibliography.ts');
    const rubric = await import('/src/utils/rubric.ts');
    const types = await import('/src/types/index.ts');
    const now = Date.now();
    const id = 'manual-editorial-salt-roads';
    const html = '<h1>Salt Roads</h1><p>Before dawn, the salt caravans left the harbour. A week of walking lay between the coast and the inland market.</p><p>The traders <span data-persona-note-id="sample-pacing" data-persona-note-author="Marguerite" data-persona-note-color="#b0413e" data-persona-note-label="Pacing" data-persona-note-note="Let the weighing stand alone. Give the weather its own sentence so the scene has room to breathe." data-persona-note-quote="weighed their loads by the handful">weighed their loads by the handful</span> and argued about the weather. Every bargain began with the weight of what could be carried.</p><p>By the fourth day <span class="twyne-comment-mark" data-comment-id="sample-route" data-comment-author="You">the road forgot the sea entirely</span> and turned inland. This was the point where the route became a story told by its travellers.</p><p>At the ford, the mules refused the water. The traders waited until afternoon, when a guide showed them the shallows.</p><p>The journey changed how the traders understood distance: a map measured miles, but a caravan measured rest, water and shelter.</p><p>For a working reference on salt and its trade, see https://www.britannica.com/science/salt and (Kurlansky, 2002).</p>';
    const text = html.replace(/<[^>]+>/g, ' ');
    await idb.saveFoliosToIdb([{ id, name: 'Salt Roads', type: 'draft', createdAt: now, updatedAt: now }]);
    await idb.saveActiveFolioIdToIdb(id);
    await idb.saveFolioContentToIdb(id, html);
    await uc.saveUserComments([{ id: 'sample-route', folioId: id, text: 'Check the route before keeping this image. Does the road turn inland here?', author: 'You', anchor: 'the road forgot the sea entirely', resolved: false, createdAt: now, updatedAt: now, replies: [] }]);
    for (const [key, value] of Object.entries({ 'live-review-enabled': false, 'in-flow-enabled': false, 'flow-reading-enabled': true, 'cover-lookup-enabled': false, 'flow-focus-enabled': false })) await idb.saveMetaToIdb(key, value);
    const settings = await idb.loadApparatusSettingsFromIdb();
    await idb.saveApparatusSettingsToIdb({ ...settings, aiEnhanceCitations: false, flagMissingSources: false, autoInsertFootnotes: false, researchProvider: 'disabled', mcpServers: [] });
    await bib.saveBibliography([
      { id: 'sample-salt', folioId: id, title: 'Salt', author: 'Encyclopaedia Britannica', publisher: 'Encyclopaedia Britannica', url: 'https://www.britannica.com/science/salt', accessedAt: now, provenance: 'writer', note: 'Working reference for the sample draft.' },
      { id: 'sample-history', folioId: id, title: 'Salt: A World History', author: 'Kurlansky, Mark', publisher: 'Walker and Company', date: '2002', year: '2002', url: '', accessedAt: now, provenance: 'writer', citationKey: 'kurlansky2002' }
    ]);
    await idb.saveRubricResultToIdb({
      folioId: id, overallGrade: 'B', overallScore: 76, scoringMethod: 'room', summary: 'A clear journey with a strong image. Verify the route and develop the evidence before the next pass.', timestamp: now,
      criteria: types.SPINE_CRITERIA.map((c, i) => ({ ...c, score: i === 2 ? 5 : i === 0 ? 8 : 7, maxScore: 10, feedback: c.id === 'evidence' ? 'The salt reference gives useful context. Add a source for the inland turn before presenting it as fact.' : 'The caravan scene supports the central idea. Keep the next revision anchored in a concrete moment.' })),
      judges: [{ personaId: 'Marguerite', score: 7.5, rationale: 'The weighing image is vivid. Separate the weather from the action so the reader can hear both.', provider: 'staged' }, { personaId: 'Dickens', score: 7, rationale: 'The journey earns its shape. Give the guide one specific action at the ford.', provider: 'staged' }],
      staticScore: rubric.scoreStaticFeatures(text), targetFit: 8,
      review: '## Keep the scene concrete\n\nThe caravan measures distance in **rest, water and shelter**. Keep that thread as you revise.\n\n## Verify before sharpening\n\nThe inland turn needs a source. Once it is grounded, split the weighing and weather into two sentences.'
    }, id);
  });
  return { browser, context, page, errors };
}

export async function ready(page) {
  await page.evaluate(() => document.fonts.ready);
  await page.waitForTimeout(800);
}

export async function capture(page, name, locator, description) {
  await ready(page);
  if (locator) await locator.scrollIntoViewIfNeeded();
  await page.waitForTimeout(300);
  const buffer = locator ? await locator.screenshot() : await page.screenshot();
  const metadata = await sharp(buffer).metadata();
  const width = Math.min(metadata.width, 1440);
  const file = `${name}.webp`;
  await sharp(buffer).resize({ width, withoutEnlargement: true }).webp({ quality: 86, effort: 5 }).toFile(`${assets}${file}`);
  const output = await sharp(`${assets}${file}`).metadata();
  captures.push({ file, width: output.width, height: output.height, description, route: new URL(page.url()).pathname });
  await page.waitForTimeout(1200);
  return captures.at(-1);
}

export async function finish(session) {
  const video = session.page.video();
  await session.context.close();
  await video.saveAs(`${recording}editorial-walkthrough.webm`);
  await session.browser.close();
  await writeFile(`${recording}capture-result.json`, JSON.stringify({ captures, pageErrors: session.errors, video: 'editorial-walkthrough.webm' }, null, 2));
}

export { expect };
import { createInterface } from 'node:readline';
import { appendFile, writeFile } from 'node:fs/promises';
import * as helper from './capture-session.mjs';
const session = await helper.boot();
const { page } = session;
const { capture, ready, expect } = helper;
const replay = new URL('./replay.mjs', import.meta.url);
await writeFile(replay, "import * as helper from './capture-session.mjs';\nconst session = await helper.boot();\nconst { page } = session;\nconst { capture, ready, expect } = helper;\n");
console.log('Capture browser ready');
for await (const line of createInterface({ input: process.stdin })) {
  try {
    const code = JSON.parse(line);
    const result = await eval(`(async () => { ${code}\n })()`);
    await appendFile(replay, `${code}\n`);
    console.log(JSON.stringify({ ok: true, result }));
    if (code.includes('helper.finish(session)')) break;
  } catch (error) {
    console.log(JSON.stringify({ ok: false, error: String(error) }));
  }
}

