};

const openSourceEditor = () => {
  if (!props.editor.options.editable || sourceEditor) return;

  render.hidden = true;
  sourceEditor = createMathSourceEditor({
    editor: props.editor,
    getPos: props.getPos,
    nodeName: display === "block" ? "blockMath" : "inlineMath",
    source: String(currentNode.attrs.source ?? ""),
