          createdAt: Date.now(),
          x: geom.x,
          top: geom.top,
          bottom: geom.bottom,
          maxH: geom.maxH,
          from: range.from,
          to: range.to,
          resolved: false,
          replies: [],
          draft: restoreDraft,
        };
        store.selectionAction = null;
      },
    );

    const submitWriterMargin = $(async () => {
      const popover = store.userCommentPopover;
      if (
        !popover ||
        popover.mode !== "compose" ||
        popover.from == null ||
        popover.to == null ||
        !popover.draft.trim()
      ) {
        return;
      }
      await createSelectionComment(
        popover.draft.trim(),
        { from: popover.from, to: popover.to },
        true,
      );
    });

    const discardWriterMargin = $(() => {
      if (store.userCommentPopover?.mode === "compose") {
        store.userCommentPopover = null;
      }
    });

    // Only a file drag gets the "Drop plate or tabular here" prompt. Dragging a
    // selection through the manuscript is an ordinary editing gesture, and
    // raising a full-surface overlay for it both lies about what will happen and
    // re-renders the panel on every dragover frame.
    const handleDragOver = $((event: DragEvent) => {
      if (!isFileDrag(event.dataTransfer)) return;
      store.isDragOver = true;
    });

    const handleDragLeave = $(() => {
      store.isDragOver = false;
    });

    const handleDrop = $(() => {
      store.isDragOver = false;
    });

    const insertImage = $((src: string, alt?: string) => {
      store.editor
        ?.chain()
        .focus()
        .insertContent({
          type: "image",
          attrs: { src, alt: alt || "", offline: src.startsWith("data:") },
        })
        .run();
    });

    const chooseImageFiles = $(async () => {
      const editor = store.editor;
      const adapter = store.imageUploadAdapter;
      if (!editor || !adapter) return;
      store.imageUploadError = null;
      await chooseAndInsertImages(editor, adapter, undefined, (error) => {
        store.imageUploadError = error.message;
      });
      store.showImageInput = false;
    });

    const patchSelectedImage = $((patch: Partial<ImageNodeAttributes>) => {
      store.editor?.chain().focus().updateAttributes("image", patch).run();
    });

    const retrySelectedImage = $(async () => {
      const editor = store.editor;
      const adapter = store.imageUploadAdapter;
      const uploadId = store.selectedImage?.uploadId;
      if (!editor || !adapter || !uploadId) return;
      store.imageUploadError = null;
"}

